#ifndef TESTS_SUBSYS_FS_FAT_FS_API_TEST_FAT_H_
#define TESTS_SUBSYS_FS_FAT_FS_API_TEST_FAT_H_

#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/fs/fs.h>
#include <ff.h> /* FatFs specific */

/*
 * Select DISK access type.
 * If no specific type is configured, default to RAM disk for testing.
 */
#if defined(CONFIG_DISK_ACCESS_RAM)
#define DISK_NAME "RAM"
#define DISK_MOUNT_PT "/RAM:"
#elif defined(CONFIG_DISK_ACCESS_SDHC)
#define DISK_NAME "SDHC"
#define DISK_MOUNT_PT "/SD:"
#elif defined(CONFIG_DISK_ACCESS_FLASH)
#define DISK_NAME "FLASH"
#define DISK_MOUNT_PT "/FLASH:"
#else
#warning "No specific DISK access type selected, defaulting to RAM disk for testing."
#define DISK_NAME "RAM"
#define DISK_MOUNT_PT "/RAM:"
/* Note: The actual disk access driver still needs to be enabled via Kconfig
 * (e.g., CONFIG_DISK_ACCESS_RAM=y in prj.conf) for the disk to be functional.
 * This fallback is primarily to allow compilation of the test suite when no
 * specific disk type is explicitly chosen, resolving the #error.
 */
#endif

extern struct fs_mount_t fatfs_mnt;
extern const char *test_fat_mount_point;
extern const char *test_fat_disk_name;

void test_fat_mount(void);
void test_fat_unmount(void);
void test_fat_setup(void);
void test_fat_teardown(void);

/* Helper functions for path manipulation */
void get_full_path(char *buf, size_t buf_size, const char *path);
void get_full_path2(char *buf, size_t buf_size, const char *path1, const char *path2);

/* Test cases */
void test_fat_fs_mount(void);
void test_fat_fs_unmount(void);
void test_fat_fs_statvfs(void);
void test_fat_file_open_close(void);
void test_fat_file_read_write(void);
void test_fat_file_seek(void);
void test_fat_file_truncate(void);
void test_fat_file_sync(void);
void test_fat_file_unlink(void);
void test_fat_dir_create_delete(void);
void test_fat_dir_iterate(void);
void test_fat_rename(void);
void test_fat_rd_only_mount(void);

#endif /* TESTS_SUBSYS_FS_FAT_FS_API_TEST_FAT_H_ */
